import { FileSessionStore, z } from 'genkit/beta';
import { ai } from './ai.js';
import { createRefund } from './db.js';
import { lookupOrder } from './tools.js';

const store = new FileSessionStore('.genkit/sessions');

const issueRefund = ai.defineTool(
  {
    name: 'issueRefund',
    description: 'Refunds an amount to the customer for an order. Only call this after approveRefund returned approved.',
    inputSchema: z.object({ orderId: z.string(), amount: z.number() }),
    outputSchema: z.object({ refundId: z.string() }),
  },
  async ({ orderId, amount }) => ({ refundId: createRefund(orderId, amount) }),
);

const approveRefund = ai.defineInterrupt({
  name: 'approveRefund',
  description: 'Asks a human to approve a refund before it is issued.',
  inputSchema: z.object({ orderId: z.string(), amount: z.number(), reason: z.string() }),
  outputSchema: z.object({ approved: z.boolean(), note: z.string().optional() }),
});

/** Answers order status questions. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  description: 'Answers questions about an order: its status, delivery date, tracking code and total.',
  system:
    'You are the Northwind Supplies order desk. Answer questions about orders using the lookupOrder tool. ' +
    'Quote the status, ETA and tracking code exactly as the tool returns them. If an order is not found, say so.',
  tools: [lookupOrder],
  maxTurns: 4,
});

/** Handles refund requests and pauses for human approval before refunding. */
export const refundAgent = ai.defineAgent({
  name: 'refundAgent',
  description: 'Handles refund requests for an order. Refunds need human approval.',
  system: 'Look up the order, then call approveRefund, then issueRefund only if approved. Never refund without approval.',
  tools: [lookupOrder, approveRefund, issueRefund],
  toolChoice: 'auto',
  maxTurns: 6,
  store,
});

const askOrderAgent = ai.defineTool(
  {
    name: 'askOrderAgent',
    description:
      'Hands an order question to the order desk and returns its answer. Include the order id in the question, for example "What is the status of order A-1001?"',
    inputSchema: z.object({ question: z.string() }),
    outputSchema: z.string(),
  },
  async ({ question }) => (await orderAgent.chat().send(question)).text,
);

const askRefundAgent = ai.defineTool(
  {
    name: 'askRefundAgent',
    description:
      'Hands a refund request to the refund desk and returns its reply. Include the order id and the reason in the request.',
    inputSchema: z.object({ request: z.string() }),
    outputSchema: z.string(),
  },
  async ({ request }) => {
    const response = await refundAgent.chat().send(request);
    return response.interrupts.length > 0 ? 'The refund is waiting for human approval and has not been issued.' : response.text;
  },
);

/** Front desk agent: answers general questions and routes order and refund requests to specialists. */
export const triage = ai.defineAgent({
  name: 'triage',
  description: 'Front desk for Northwind Supplies. Routes order and refund requests to specialists and keeps the conversation going.',
  system:
    'You are the Northwind Supplies front desk. Greet customers and answer general questions briefly yourself. ' +
    'For questions about an order, call askOrderAgent. For refund requests, call askRefundAgent. ' +
    'Never answer order or refund questions yourself. ' +
    'Include the order id and any other details the customer gave earlier in the conversation in the question or request you pass on. ' +
    'Give the customer the specialist answer as it was returned.',
  tools: [askOrderAgent, askRefundAgent],
  maxTurns: 4,
  store,
});
